        [<Interface>]
        type TestConfig<'TestArgs, 'WorkerArgs> =
            /// <summary>
            /// Playwright Test supports running multiple test projects at the same time. See
            /// [TestProject](https://playwright.dev/docs/api/class-testproject) for more information.
            ///
            /// **Usage**
            ///
            /// <code lang="js">
            /// // playwright.config.ts
            /// import { defineConfig, devices } from '@playwright/test';
            ///
            /// export default defineConfig({
            ///   projects: [
            ///     { name: 'chromium', use: devices['Desktop Chrome'] }
            ///   ]
            /// });
            /// </code>
            /// </summary>
            abstract member projects: ResizeArray<Playwright.types_test.Project<'TestArgs, 'WorkerArgs>> option with get, set
            /// <summary>
            /// The list of reporters to use. Each reporter can be:
            /// - A builtin reporter name like <c>'list'</c> or <c>'json'</c>.
            /// - A module name like <c>'my-awesome-reporter'</c>.
            /// - A relative path to the reporter like <c>'./reporters/my-awesome-reporter.js'</c>.
