        [<Interface>]
        type TestDetails =
            abstract member tag: U2<string, ResizeArray<string>> option with get, set
            abstract member annotation: U2<Playwright.types_test.TestDetailsAnnotation, ResizeArray<Playwright.types_test.TestDetailsAnnotation>> option with get, set
            abstract member lock: U2<string, ResizeArray<string>> option with get, set

        type TestBody<'TestArgs> =
            delegate of args: 'TestArgs * testInfo: Playwright.types_test.TestInfo -> U2<JS.Promise<obj>, obj>

        type ConditionBody<'TestArgs> =
            delegate of args: 'TestArgs -> bool

