    /// <summary>
    /// Playwright has **experimental** support for Electron automation. You can access electron namespace via:
    ///
    /// <code lang="js">
    /// const { _electron } = require('playwright');
    /// </code>
    ///
    /// An example of the Electron automation script would be:
    ///
    /// <code lang="js">
    /// const { _electron: electron } = require('playwright');
    ///
    /// (async () => {
    ///   // Launch Electron app.
    ///   const electronApp = await electron.launch({ args: ['main.js'] });
    ///
    ///   // Evaluation expression in the Electron context.
    ///   const appPath = await electronApp.evaluate(async ({ app }) => {
    ///     // This runs in the main Electron process, parameter here is always
    ///     // the result of the require('electron') in the main app script.
    ///     return app.getAppPath();
    ///   });
    ///   console.log(appPath);
    ///
    ///   // Get the first window that the app opens, wait if necessary.
    ///   const window = await electronApp.firstWindow();
    ///   // Print the title.
    ///   console.log(await window.title());
    ///   // Capture a screenshot.
    ///   await window.screenshot({ path: 'intro.png' });
    ///   // Direct Electron console to Node terminal.
    ///   window.on('console', console.log);
    ///   // Click button.
    ///   await window.click('text=Click me');
    ///   // Exit app.
    ///   await electronApp.close();
    /// })();
    /// </code>
    ///
    /// **Supported Electron versions are:**
    /// - v12.2.0+
    /// - v13.4.0+
    /// - v14+
    ///
    /// **Known issues:**
    ///
    /// If you are not able to launch Electron and it will end up in timeouts during launch, try the following:
    /// - Ensure that <c>nodeCliInspect</c>
    ///   ([FuseV1Options.EnableNodeCliInspectArguments](https://www.electronjs.org/docs/latest/tutorial/fuses#nodecliinspect))
    ///   fuse is **not** set to <c>false</c>.
    ///
    /// **Mocking native dialogs:**
    ///
    /// Playwright does not intercept the native Electron [dialog](https://www.electronjs.org/docs/latest/api/dialog) API
    /// (<c>dialog.showOpenDialog</c>, <c>dialog.showSaveDialog</c>, <c>dialog.showMessageBox</c>, etc.) because those calls happen in the
    /// Electron main process and go straight to OS APIs. Use
    /// [electronApplication.evaluate(pageFunction[, arg])](https://playwright.dev/docs/api/class-electronapplication#electron-application-evaluate)
    /// to replace the relevant methods in the main process so tests run deterministically without any OS-level UI:
    ///
    /// <code lang="js">
    /// // Stub the open dialog to always return a fixed path.
    /// await electronApp.evaluate(({ dialog }, filePaths) => {
    ///   dialog.showOpenDialog = () => Promise.resolve({ canceled: false, filePaths });
    /// }, ['/path/to/file.txt']);
    ///
    /// // Stub the save dialog.
    /// await electronApp.evaluate(({ dialog }, filePath) => {
    ///   dialog.showSaveDialog = () => Promise.resolve({ canceled: false, filePath });
    /// }, '/path/to/saved.txt');
    ///
    /// // Stub showMessageBox to click the first button.
    /// await electronApp.evaluate(({ dialog }) => {
    ///   dialog.showMessageBox = () => Promise.resolve({ response: 0, checkboxChecked: false });
    /// });
    /// </code>
    ///
    /// The replacement persists until the application is closed. Synchronous variants (<c>showOpenDialogSync</c>,
    /// <c>showSaveDialogSync</c>, <c>showMessageBoxSync</c>) can be stubbed the same way — just return the value directly instead of
    /// a <c>Promise</c>.
    /// </summary>
    [<AllowNullLiteral>]
    [<Interface>]
    type Electron =
        /// <summary>
        /// Launches electron application specified with the
        /// [<c>executablePath</c>](https://playwright.dev/docs/api/class-electron#electron-launch-option-executable-path).
        /// </summary>
        /// <param name="options">
        ///
        /// </param>
        abstract member launch: ?options: Electron.launch.options -> JS.Promise<PlaywrightCore.ElectronApplication>

    /// <summary>
    /// Playwright has **experimental** support for Android automation. This includes Chrome for Android and Android
    /// WebView.
    ///
    /// *Requirements*
    /// - Android device or AVD Emulator.
    /// - [ADB daemon](https://developer.android.com/studio/command-line/adb) running and authenticated with your device.
    ///   Typically running <c>adb devices</c> is all you need to do.
    /// - [<c>Chrome 87</c>](https://play.google.com/store/apps/details?id=com.android.chrome) or newer installed on the
    ///   device
    /// - "Enable command line on non-rooted devices" enabled in <c>chrome://flags</c>.
    ///
    /// *Known limitations*
    /// - Raw USB operation is not yet supported, so you need ADB.
    /// - Device needs to be awake to produce screenshots. Enabling "Stay awake" developer mode will help.
    /// - We didn't run all the tests against the device, so not everything works.
    ///
    /// *How to run*
    ///
    /// An example of the Android automation script would be:
    ///
    /// <c></c><c>js
    /// const { _android: android } = require('playwright');
    ///
    /// (async () => {
    ///   // Connect to the device.
    ///   const [device] = await android.devices();
    ///   console.log(</c>Model: ${device.model()}<c>);
    ///   console.log(</c>Serial: ${device.serial()}<c>);
    ///   // Take screenshot of the whole device.
    ///   await device.screenshot({ path: 'device.png' });
    ///
    ///   {
    ///     // --------------------- WebView -----------------------
    ///
    ///     // Launch an application with WebView.
    ///     await device.shell('am force-stop org.chromium.webview_shell');
    ///     await device.shell('am start org.chromium.webview_shell/.WebViewBrowserActivity');
    ///     // Get the WebView.
    ///     const webview = await device.webView({ pkg: 'org.chromium.webview_shell' });
    ///
    ///     // Fill the input box.
    ///     await device.fill({
    ///       res: 'org.chromium.webview_shell:id/url_field',
    ///     }, 'github.com/microsoft/playwright');
    ///     await device.press({
    ///       res: 'org.chromium.webview_shell:id/url_field',
    ///     }, 'Enter');
    ///
    ///     // Work with WebView's page as usual.
    ///     const page = await webview.page();
    ///     await page.waitForNavigation({ url: /.*microsoft\/playwright.*\/ });
    ///     console.log(await page.title());
    ///   }
    ///
    ///   {
    ///     // --------------------- Browser -----------------------
    ///
    ///     // Launch Chrome browser.
    ///     await device.shell('am force-stop com.android.chrome');
    ///     const context = await device.launchBrowser();
    ///
    ///     // Use BrowserContext as usual.
    ///     const page = await context.newPage();
    ///     await page.goto('https://webkit.org/');
    ///     console.log(await page.evaluate(() => window.location.href));
    ///     await page.screenshot({ path: 'page.png' });
    ///
    ///     await context.close();
    ///   }
    ///
    ///   // Close the device.
    ///   await device.close();
    /// })();
    /// </c><c></c>
    /// </summary>
    [<AllowNullLiteral>]
    [<Interface>]
    type Android =
        /// <summary>
